input.command:
find testdata/public -name "*.edf" | while read f; do .venv/bin/python -c "
import sys;f=sys.argv[1];b=open(f,'rb').read(256);ns=int(b[252:256]);h=open(f,'rb').read(256+256*ns);off=256+ns*(16+80+8*6)
print(f.split('/')[2], b[192:200], repr(h[off:off+80].strip()))" "$f"; done; for d in testdata/public/*/native-export; do .venv/bin/python -m cwelleegread inspect "$d" --max-events 0 | head -1 | sed 's/patient [^ ]*//'; done; du -sh testdata/public/*; git log --oneline | wc -l; git count-objects -vH | tail -2

